#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with DATE"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" = '' ] || { echo "list --room with DATE should filter both"; fail=1; }
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>&1; [ $? = 2 ] || { echo "list --room without ROOM should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null)" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without ROOM usage"; fail=1; }
rm -f "$t"; exit $fail

